   [166]={next_id=167, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她确实帮了我很大的忙，不过我也救过她一次，所以……我们应该算某种意义上交过生死的伙伴。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_14_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [167]={next_id=168, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="至于别的关系……以她的性子见到我，估计还是像福登城那样，一边提刀狂笑着，一边问我她是不是又创造斩杀修格尔数量的新纪录了。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_14_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [168]={next_id=169, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="噗…… 听起来感觉是个很热血的人呢，倒不像难相处的样子。", msg_color="", msg_size=0, talker="艾丽西亚", audio="", img="arts/ui/bg/story/storybg_14_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3101_1", 0, 0, 8, 176.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [169]={next_id=170, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="难相处倒也说不上，总之……见过以后你就知道了。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_14_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3101_1", 0, 0, 8, 176.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [170]={next_id=171, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="有她们帮忙，我们在极北寻找那段未知频率，也会轻松不少。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_14_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3101_1", 0, 0, 8, 176.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [171]={next_id=172, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="嗯，那你的神血链接……", msg_color="", msg_size=0, talker="艾丽西亚", audio="", img="arts/ui/bg/story/storybg_14_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3101_1", 0, 0, 8, 176.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [172]={next_id=173, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="有弦枝在，暂时没什么大问题，她的星源共鸣能稳定我的精神，这样的能力在泰诺星也很少见。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_14_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3101_1", 0, 0, 8, 176.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [173]={next_id=174, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="所以，能遇到她和涅普露，不知道该说是巧合，还是命运的安排。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_14_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3101_1", 0, 0, 8, 176.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
